class ChainNode:
    def __init__(self, value, next=None):
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("value must be an integer")
        if next is not None and not isinstance(next, ChainNode):
            raise ValueError("next must be a ChainNode or None")
        self.value = value
        self.next = next


def _merge_two(left, right):
    dummy = ChainNode(0)
    tail = dummy
    while left is not None and right is not None:
        if left.value < right.value:
            tail.next = left
            left = left.next
        else:
            tail.next = right
            right = right.next
        tail = tail.next
    tail.next = left if left is not None else right
    return dummy.next


def merge_sorted_chains(heads):
    if not isinstance(heads, list):
        raise ValueError("heads must be a list")

    seen = set()
    for head in heads:
        if head is not None and not isinstance(head, ChainNode):
            raise ValueError("invalid head")
        node = head
        previous = None
        local = set()
        while node is not None:
            if not isinstance(node, ChainNode):
                raise ValueError("invalid next reference")
            marker = id(node)
            if marker in local:
                raise ValueError("cycle detected")
            if marker in seen:
                raise ValueError("shared node detected")
            local.add(marker)
            seen.add(marker)
            if previous is not None and previous > node.value:
                raise ValueError("chain is not sorted")
            previous = node.value
            node = node.next

    work = list(heads)
    interval = 1
    while interval < len(work):
        for index in range(0, len(work) - interval, interval * 2):
            work[index] = _merge_two(work[index], work[index + interval])
        interval *= 2
    return work[0] if work else None

